/* MIT. Physical opening encounter. Only real kill/escort/parcel events earn proof. */
#ifndef MYRO_CAMPAIGN_RESCUE200_H
#define MYRO_CAMPAIGN_RESCUE200_H
#include "campaign_state200.h"
#include "chapter1_data200.h"
#include "npc_monsters55.h"
#define RESCUE_TAG200 UINT32_C(0xec200010)
enum{R200_NERA,R200_ROAN,R200_YUUFA,R200_DRIVER,R200_PARCEL};
typedef struct{Combat*player;NpcMonsters55*monsters;NpcState55*state;unsigned active,escort,pendingKills,stage;float driverX,driverY;}CampaignRescue200;
static CampaignRescue200 campaignRescue200;
static int rescue_owned200(const NpcMonster55*m){return m->npc==UINT32_MAX&&(m->entry==RESCUE_TAG200||m->entry==RESCUE_TAG200+1);}
static void rescue_clear_mobs200(CampaignRescue200*r){if(!r->monsters)return;for(unsigned i=0;i<r->monsters->count;i++){NpcMonster55*m=r->monsters->rows+i;if(!rescue_owned200(m))continue;if(r->player&&m->slot>=0&&m->slot<MOB_COUNT){CombatMob*b=r->player->mobs+m->slot;if(b->npcSpawn55==i+1&&b->life==m->serial)b->enabled=0;}m->alive=0;m->hp=0;}if(r->player)npc_monster_recycle55(r->monsters,r->player);}
static void rescue_reset200(CampaignRescue200*r){rescue_clear_mobs200(r);memset(r,0,sizeof(*r));}
static int rescue_store_kills200(CampaignRescue200*r){Campaign200 c;if(!r->pendingKills)return 1;if(campaign_load200(r->state,&c)!=1||c.cursor)return 0;c.objectives|=r->pendingKills;if((c.objectives&24u)==24u)c.objectives|=4u;if(!campaign_store200(r->state,&c))return 0;r->pendingKills=0;return 1;}
static void rescue_killed200(CampaignRescue200*r,Combat*g,const CombatMob*mob){if(!r->active||r->player!=g||g->mapId||g->hp<=0||!mob->npcSpawn55||!r->monsters)return;unsigned i=mob->npcSpawn55-1;if(i>=r->monsters->count)return;const NpcMonster55*m=r->monsters->rows+i;if(!rescue_owned200(m)||m->serial!=mob->life||!m->alive||mob->hp>0||mob->training)return;r->pendingKills|=1u<<(3+m->entry-RESCUE_TAG200);rescue_store_kills200(r);}
static void rescue_position200(const CampaignRescue200*r,unsigned actor,float*x,float*y){static const float p[5][2]={{1452,2820},{1436,2788},{1476,2820},{1468,2780},{1484,2788}};if(actor>4)actor=0;*x=actor==R200_DRIVER?r->driverX:p[actor][0];*y=actor==R200_DRIVER?r->driverY:p[actor][1];}
/* Setup is inert until its scene graphics are ready; no invisible interactions. */
static void rescue_bind200(CampaignRescue200*r,Combat*g,NpcMonsters55*monsters,NpcState55*state,int graphicsReady){Campaign200 c;if(!graphicsReady||!state||campaign_load200(state,&c)!=1||c.cursor>=3||g->mapId){rescue_reset200(r);return;}if(r->player!=g||r->state!=state||r->monsters!=monsters){rescue_reset200(r);r->player=g;r->monsters=monsters;r->state=state;r->driverX=1468;r->driverY=2780;}r->active=1;if(r->stage!=c.cursor){rescue_clear_mobs200(r);r->stage=c.cursor;r->escort=r->pendingKills=0;r->driverY=2780;}if(!c.cursor&&(c.objectives&1)){r->driverY=2812;r->escort=0;}}
static int rescue_present200(CampaignRescue200*r,unsigned enemy){for(unsigned i=0;i<r->monsters->count;i++){NpcMonster55*m=r->monsters->rows+i;if(!rescue_owned200(m)||m->entry!=RESCUE_TAG200+enemy||!m->alive)continue;if(m->slot>=0&&m->slot<MOB_COUNT){const CombatMob*b=r->player->mobs+m->slot;if(b->enabled&&b->npcSpawn55==i+1&&b->life==m->serial)return 1;}m->alive=0;m->hp=0;m->slot=-1;}return 0;}
static int rescue_spawn200(CampaignRescue200*r){Campaign200 c;if(!r->active||campaign_load200(r->state,&c)!=1||c.cursor||c.checkpoint!=CHAPTER1_RESCUE_GATE200||(c.objectives&4))return 1;Combat*g=r->player;NpcMonsters55*s=r->monsters;if(g->hp<=0||combat_dist(g->x,g->y,1460,2804)>192)return 1;unsigned missing=0,freeSlots=0;for(unsigned i=0;i<MOB_COUNT-1;i++)freeSlots+=!g->mobs[i].enabled;for(unsigned k=0;k<2;k++){if(c.objectives&(1u<<(3+k)))continue;int present=rescue_present200(r,k);if(!present)missing++;}if(!missing)return 1;if(missing>freeSlots||!npc_monster_reserve55(s,missing))return 0;int kind=npc_monster_kind55(1002);if(kind<0)return 0;for(unsigned k=0;k<2;k++){if(c.objectives&(1u<<(3+k)))continue;int present=rescue_present200(r,k);if(present)continue;NpcMonster55 row={0};row.map=0;row.kind=(unsigned)kind;row.serial=++s->serial;if(!row.serial)row.serial=++s->serial;row.npc=UINT32_MAX;row.entry=RESCUE_TAG200+k;row.slot=-1;row.hp=mobSpecs[kind].hp;row.alive=1;row.x=k?1484:1436;row.y=2780;snprintf(row.name,sizeof(row.name),"Poring");unsigned index=s->count++;s->rows[index]=row;if(!npc_monster_attach55(s,index,g)){rescue_clear_mobs200(r);return 0;}}return 1;}
static void rescue_tick200(CampaignRescue200*r,float dt,int paused){if(!r->active||paused)return;Combat*g=r->player;Campaign200 c;if(campaign_load200(r->state,&c)!=1||c.cursor>=3||g->mapId){rescue_reset200(r);return;}if(c.cursor)return;if(g->hp<=0){rescue_clear_mobs200(r);r->escort=0;if(!(c.objectives&1)){r->driverX=1468;r->driverY=2780;}return;}if(!rescue_store_kills200(r))return;if(!rescue_spawn200(r))return;if(!r->escort)return;if(combat_dist(g->x,g->y,r->driverX,r->driverY)>64)return;if(dt<0||!isfinite(dt))return;if(dt>.05f)dt=.05f;float ny=fminf(2812,r->driverY+32*dt);if(g->canMove&&!g->canMove(g->world,r->driverX,r->driverY,r->driverX,ny))return;r->driverY=ny;if(ny>=2812&&campaign_objective200(r->state,0,0))r->escort=0;}
static int rescue_near200(const CampaignRescue200*r){if(!r->active||r->player->hp<=0)return-1;Campaign200 c;if(campaign_load200(r->state,&c)!=1||c.cursor>=3)return-1;int best=-1;float distance=20;for(unsigned i=0;i<5;i++){if(i==R200_PARCEL&&(c.cursor||c.objectives&2))continue;float x,y;rescue_position200(r,i,&x,&y);float d=combat_dist(r->player->x,r->player->y,x,y);if(d<distance){distance=d;best=(int)i;}}return best;}
/* Return1 to open/resume authored dialogue; other actions never advance text. */
static int rescue_interact200(CampaignRescue200*r,unsigned who){Campaign200 c;if(!r->active||who>4||rescue_near200(r)!=(int)who||campaign_load200(r->state,&c)!=1||c.cursor>=3)return 0;if(c.cursor)return who<R200_PARCEL;Combat*g=r->player;if(who!=R200_DRIVER&&who!=R200_PARCEL)return 1;if(c.checkpoint<CHAPTER1_RESCUE_GATE200){combat_message(g,"Speak with Nera beside the road first.");return 0;}if(who==R200_PARCEL){if(!(c.objectives&1)){combat_message(g,"The driver needs help first. The parcel can wait.");return 0;}if(campaign_objective200(r->state,0,1))combat_message(g,"Recovered the reports tied with a blue cord.");return 0;}if(c.objectives&1){combat_message(g,"The driver is safe. Recover the blue-cord parcel.");return 0;}if(!(c.objectives&4)){combat_message(g,"Clear the two Porings so the driver can get free.");return 0;}r->escort=1;combat_message(g,"Stay close and lead the driver back to Nera.");return 0;}
#endif
